def write_rotated_assets(full_pdf,asset_dir,crop_manifest,pdf_stamp):
 cover=max(full_pdf.pages[179].images,key=lambda item:item.image.width*item.image.height).image.rotate(-90,expand=True)
 for name,rect in [('back-campus-photograph',(0,0,1157,355)),('back-publisher-emblem',(235,1240,395,1410))]:
  key=pdf_stamp+':180:rotation=-90:'+str(rect)
  target=asset_dir/(name+'.jpg')
  if crop_manifest.get(name)!=key or not target.exists():cover.crop(rect).convert('RGB').save(target,quality=95)
  crop_manifest[name]=key
